/* Áurea: contenido de la app en inglés. Se carga solo cuando la persona elige English.
   Cada bloque reemplaza, con la misma estructura, el texto en español de app.html. */
window.AUREA_EN={"caps":{"s1":{"title":"Focus on what is up to you","origin":"Stoicism","ref":"The “dichotomy of control” of Epictetus, Greek philosopher of the 1st century."},"s2":{"title":"Why we suffer and what we can do","origin":"Buddhism","ref":"The Four Noble Truths: suffering exists, it has a cause, it can end, and there is a path to end it."},"s3":{"title":"When you need others to approve of you","origin":"Psychology and Buddhism","ref":"The ego as identification with one’s own image, and attachment to the opinion of others."},"s4":{"title":"Nothing lasts, and that is good news","origin":"Buddhism and Stoicism","ref":"Impermanence (anicca in Buddhism); Marcus Aurelius also describes it in his Meditations."},"s5":{"title":"Living with the knowledge that time is limited","origin":"Stoicism","ref":"The Roman practice of memento mori, “remember that you will die”."},"s6":{"title":"Loving the life you are given","origin":"Stoicism","ref":"Amor fati, “love of fate”, present in Epictetus and Marcus Aurelius, and made popular by Nietzsche."},"s7":{"title":"Flowing instead of forcing","origin":"Taoism","ref":"Wu wei, “effortless action”, from the Tao Te Ching of Lao Tzu."},"s8":{"title":"Having without being had","origin":"Buddhism","ref":"Attachment (upādāna) as the root of suffering, and letting go as freedom."},"s9":{"title":"Forgiving to let go, not to forget","origin":"Contemplative traditions","ref":"Forgiveness is present in Buddhism, Christianity and modern psychology as a tool for healing."},"s10":{"title":"Responding instead of reacting","origin":"Emotional intelligence and Stoicism","ref":"Self-regulation as described by Daniel Goleman, and Epictetus’s idea: we are not disturbed by things, but by our interpretation of them."},"s11":{"title":"As within, so without","origin":"Hermeticism","ref":"The principle of correspondence: “as above, so below; as within, so without”."},"s12":{"title":"Good days and bad days have a rhythm","origin":"Hermeticism","ref":"The principle of rhythm, one of the seven principles of The Kybalion."},"s13":{"title":"An eight-step path to live better","origin":"Buddhism","ref":"The Noble Eightfold Path, the way the Buddha proposed to leave suffering behind."},"s14":{"title":"Nothing exists on its own","origin":"Buddhism","ref":"Emptiness (śūnyatā): nothing has a separate, independent existence."},"s15":{"title":"Your words build your day","origin":"Metaphysics","ref":"The power of the word, a central idea of Florence Scovel Shinn and Conny Méndez."},"m1":{"title":"What you were told about money","origin":"Psychology of money","ref":"The study of inherited financial beliefs, the basis of many prosperity mindset programs."},"m2":{"title":"The voice that speaks inside you","origin":"Cognitive psychology","ref":"The work on inner dialogue and cognitive restructuring (Aaron Beck, Albert Ellis)."},"m3":{"title":"Pay yourself first","origin":"Classic personal finance","ref":"A principle made popular by George S. Clason in 1926."},"m4":{"title":"Knowing where your money goes","origin":"Personal finance","ref":"The budget and expense tracking, the basis of all financial planning."},"m5":{"title":"A cushion for peace of mind","origin":"Personal finance","ref":"The emergency fund, recommended by most financial planners."},"m6":{"title":"Getting out of debt step by step","origin":"Personal finance","ref":"The “snowball” method for paying off debt."},"m7":{"title":"What adds to your wealth and what takes away","origin":"Financial education","ref":"The distinction between assets and liabilities, made popular by Robert Kiyosaki."},"m8":{"title":"Money that works for you","origin":"Financial mathematics","ref":"Compound interest, the basis of all long-term investing."},"m9":{"title":"Earning more starts with giving more","origin":"Philosophy of success","ref":"The law of compensation described by Ralph Waldo Emerson."},"m10":{"title":"Small steps, big changes","origin":"Science of habits","ref":"Micro-habits, made popular by James Clear and BJ Fogg."},"m11":{"title":"Failure as a starting point","origin":"Growth psychology","ref":"The growth mindset, researched by Carol Dweck at Stanford University."},"m12":{"title":"Don’t put all your eggs in one basket","origin":"Investment principles","ref":"Diversification, one of the foundations of modern portfolio theory."},"m13":{"title":"Your talent is an asset too","origin":"Professional development","ref":"Investment in human capital, a concept from economist Gary Becker."},"m14":{"title":"Being grateful for what you already have","origin":"Metaphysics","ref":"Gratitude as the basis of prosperity, in “The Science of Getting Rich” by Wallace D. Wattles."},"v1":{"title":"Water and light when you wake up","origin":"Lifestyle medicine","ref":"Research on the circadian rhythm."},"v2":{"title":"Walking as medicine","origin":"Lifestyle medicine","ref":"The WHO recommendation of at least 150 minutes of moderate physical activity per week."},"v3":{"title":"Back to real food","origin":"Nutrition","ref":"The NOVA classification of foods by their degree of processing."},"v4":{"title":"Sleeping better starts during the day","origin":"Sleep medicine","ref":"Sleep hygiene recommendations."},"v5":{"title":"Breathing to lower stress","origin":"Physiology and contemplative traditions","ref":"Slow breathing and the parasympathetic nervous system; also the pranayama of yoga."},"v6":{"title":"Half the plate with plants","origin":"Nutrition","ref":"The “Healthy Eating Plate” from the Harvard School of Public Health."},"v7":{"title":"Strength at any age","origin":"Exercise medicine","ref":"The WHO recommendation to train strength at least two days a week."},"v8":{"title":"Eating with attention","origin":"Mindful eating","ref":"Mindful eating, which comes from the practice of mindfulness."},"v9":{"title":"Less screen time before bed","origin":"Sleep medicine","ref":"The effect of night-time light on melatonin production."},"v10":{"title":"Hidden sugar","origin":"Nutrition","ref":"The WHO recommendation to limit free sugars to less than 10% of daily energy."},"v11":{"title":"Moving every hour","origin":"Lifestyle medicine","ref":"Research on sedentary behavior and active breaks."},"v12":{"title":"Back to nature","origin":"Lifestyle medicine","ref":"Shinrin-yoku or “forest bathing”, studied in Japan since the 1980s."},"v13":{"title":"Relationships that give health","origin":"Psychology and health","ref":"The Harvard Study of Adult Development, begun in 1938."},"v14":{"title":"As you think, so you feel","origin":"Metaphysics and Psychology","ref":"“As a Man Thinketh” by James Allen (1903), and cognitive therapy."}},"trad":{"estoicismo":{"n":"Stoicism","ln":"Stoicism","t":"A school of philosophy born in Athens around 300 BC with Zeno of Citium, who taught under a painted porch (the “stoa”, hence its name). Its great Roman teachers were Seneca, adviser to Nero; Epictetus, a slave who became a teacher; and Marcus Aurelius, emperor of Rome. They taught that happiness does not depend on what happens to us, but on how we respond, and that the four virtues worth cultivating are wisdom, justice, courage and temperance."},"budismo":{"n":"Buddhism","ln":"Buddhism","t":"A tradition born in northern India around the 5th century BC with Siddhartha Gautama, a prince who left his palace to understand why we suffer. After years of searching he reached “awakening” and became known as the Buddha, “the awakened one”. More than a religion with gods, it is a practical method to observe the mind, let go of what binds us and live with compassion. Today more than 500 million people practice it, and science studies many of its techniques, such as meditation."},"taoismo":{"n":"Taoism","ln":"Taoism","t":"A Chinese philosophy attributed to Lao Tzu, a sage who, according to tradition, lived around the 6th century BC and wrote the Tao Te Ching, a short book of 81 poems. The “Tao” is the way, or the natural order of things: the rhythm with which plants grow, rivers run and seasons change. Taoism proposes living in harmony with that order, with simplicity and gentleness, instead of imposing our force on it."},"hermetismo":{"n":"Hermeticism","ln":"Hermeticism","t":"A current of thought that arose in Hellenistic Egypt in the first centuries of our era, attributed to the legendary figure of Hermes Trismegistus, “the thrice great”. It influenced alchemy, the Renaissance and many modern spiritual schools. In 1908 The Kybalion was published, summarizing its teachings in seven principles: mentalism, correspondence, vibration, polarity, rhythm, cause and effect, and gender."},"contemplativas":{"n":"Contemplative traditions","ln":"the contemplative traditions","t":"This is the name for the set of introspective practices shared by many cultures: Buddhist meditation, silent Christian prayer, the yoga of India or Sufi contemplation. Although they were born in different places, they agree on one thing: training attention and the heart changes the way we live. Today psychology and neuroscience study their effects on stress, emotions and health."},"psicologia":{"n":"Modern psychology","ln":"modern psychology","t":"Psychology studies how we think, feel and act. In the 20th century, researchers like Aaron Beck and Albert Ellis showed that many painful emotions come from automatic thoughts we can learn to recognize and change: this is the basis of cognitive therapy, one of the most studied in the world. Interestingly, both acknowledged that the idea was already present in the Stoics."},"emocional":{"n":"Emotional intelligence","ln":"emotional intelligence","t":"A concept proposed by psychologists Peter Salovey and John Mayer in 1990 and made popular by Daniel Goleman in 1995. It describes the ability to recognize and manage our own emotions and those of others. Its five pillars are self-awareness, self-regulation, motivation, empathy and social skills. According to Goleman, it matters as much as IQ for personal and professional success."},"dinero":{"n":"The psychology of money","ln":"the psychology of money","t":"A discipline that combines economics and psychology to understand why we make the financial decisions we make. Its research shows that we do not handle money with numbers alone: we do it with emotions, fears and beliefs learned in childhood. That is why two people with the same income can have very different financial lives."},"finanzas":{"n":"Personal finance","ln":"personal finance","t":"The art of managing the money of a person or a family: earning, spending, saving, investing and protecting yourself against the unexpected. Its principles are simple and have been repeated for centuries, from the clay tablets of Babylon to today’s planners. The hard part is not understanding them, but applying them consistently."},"inversion":{"n":"Investment principles","ln":"investment principles","t":"Investing is putting money to work so it grows over time. Modern investment theory was born in 1952 with Harry Markowitz, who won the Nobel Prize for proving mathematically that spreading money across different assets reduces risk without giving up much return. Its three allies are time, consistency and diversification."},"exito":{"n":"The philosophy of success","ln":"the philosophy of success","t":"A current of thought, mostly American, that studies what makes people prosper. It began in the 19th century with essayists like Ralph Waldo Emerson and continued with authors such as Napoleon Hill and Stephen Covey. It holds that lasting success depends more on character, service and habits than on luck."},"habitos":{"n":"The science of habits","ln":"the science of habits","t":"A branch of behavioral psychology that studies how routines are formed and changed. Researchers like BJ Fogg, of Stanford University, and writers like James Clear showed that a habit has three parts: a cue, an action and a reward. Its great lesson: big changes are built from small actions repeated every day."},"crecimiento":{"n":"Growth psychology","ln":"growth psychology","t":"A field of research led by Carol Dweck, professor at Stanford University. After decades of studies she found that people who believe their abilities can be developed (a “growth mindset”) learn more and recover better from failure than those who believe their talent is fixed."},"profesional":{"n":"Professional development","ln":"professional development","t":"It studies how people grow in their work and increase their value throughout their lives. It builds on the human capital theory of economist Gary Becker, Nobel laureate in 1992, who showed that education and skills are an investment with a return, just like a machine or a piece of land."},"estilo":{"n":"Lifestyle medicine","ln":"lifestyle medicine","t":"A medical specialty that uses daily habits as treatment: nutrition, physical activity, sleep, stress management, healthy relationships and avoiding harmful substances. It is backed by medical colleges in the United States and Europe, and the World Health Organization estimates that most chronic diseases can be prevented with these six pillars."},"nutricion":{"n":"Nutrition science","ln":"nutrition science","t":"It studies how food affects our body and our health. In recent decades it has moved from counting calories to looking at the quality of what we eat: how processed it is, how much fiber it provides and how it influences our energy, our mood and our gut."},"sueno":{"n":"Sleep medicine","ln":"sleep medicine","t":"A specialty that studies what happens while we sleep and how to sleep better. Today we know sleep is not wasted time: it is when the brain organizes memory, the body repairs itself, and hunger and mood are regulated. Its basis is the circadian rhythm, the internal clock of about 24 hours that syncs with light."},"ejercicio":{"n":"Exercise medicine","ln":"exercise medicine","t":"It studies movement as a health tool. Its research shows that regular exercise lowers the risk of heart disease, diabetes, depression and cognitive decline, and that it is never too late to start: the benefits appear at any age."},"metafisica":{"n":"Metaphysics","ln":"Metaphysics","t":"In philosophy, metaphysics is the branch that asks about what lies beyond the visible; the name comes from the works of Aristotle. In today’s language, “Metaphysics” also often refers to a spiritual current born in the United States in the 19th century, New Thought, with authors such as Ralph Waldo Emerson, Emmet Fox and Joseph Murphy, and in Latin America with the Venezuelan Conny Méndez. Its central idea is that our thoughts, words and beliefs shape the way we live. Science has not proven that thought changes reality by itself, but psychology does confirm that what we repeat influences how we feel and how we act."},"atencion":{"n":"Mindfulness","ln":"mindfulness","t":"Mindfulness is the practice of paying attention to the present moment, with curiosity and without judgment. It comes from Buddhist meditation and reached medicine in 1979, when Jon Kabat-Zinn created a stress reduction program at the University of Massachusetts that is now used in hospitals around the world."}},"learn":{"s1":{"idea":"Epictetus taught that some things are up to us (what we think, decide and do) and some are not (what others think, the economy, the weather, the past). Much of our distress comes from wanting to control the second. The Stoics propose putting all our energy into the first and accepting the rest calmly.","q":"Some things are within our power, while others are not.","qa":"Epictetus, Enchiridion","bk":"The Enchiridion (Handbook), by Epictetus"},"s2":{"idea":"It was the Buddha’s first teaching. First truth: life contains pain and dissatisfaction. Second: its cause is the desire for things to be different from how they are. Third: that suffering can end. Fourth: there is a practical path to end it, the Eightfold Path. It works like a medical diagnosis: symptom, cause, prognosis and treatment.","q":"I teach suffering and the end of suffering.","qa":"Attributed to the Buddha","bk":"The Heart of the Buddha’s Teaching, by Thich Nhat Hanh"},"s3":{"idea":"The need for approval has two explanations that complement each other.","by":{"budismo":"The Buddha taught anattā, “non-self”: what we call “I” is not something fixed, but a sum of thoughts, memories and labels that change. When we identify with that image (I am successful, I am a good person, I am smart), any criticism feels like an attack and we live defending it. Buddhist practice proposes observing the ego with curiosity, without obeying it.","psicologia":"Modern psychology calls this contingent self-esteem: a sense of worth that depends on the approval of others. Studies show it is fragile, rises and falls with every comment and creates anxiety. The healthy kind is self-esteem based on your values and your effort, not on other people’s opinions."},"q":"If you want to improve, be content to be thought foolish and stupid with regard to external things.","qa":"Epictetus","bk":"Ego Is the Enemy, by Ryan Holiday"},"s4":{"idea":"Two traditions born thousands of kilometers apart, with no contact between them, reached the same conclusion: nothing stays the same.","by":{"budismo":"Anicca, impermanence, is one of the three marks of existence taught by the Buddha: everything that is born changes and ends, including our emotions, possessions and relationships. Suffering appears when we cling to something as if it would last forever. Buddhist meditation invites us to watch each thought and each sensation arise and pass.","estoicismo":"For the Stoics, the universe is a constant flow of change guided by reason, which they called logos. Marcus Aurelius writes in his Meditations that everything is transformed and that time is like a river that sweeps each thing away as soon as it appears; that is why he advised enjoying what we have as something on loan, and remembering that praise and insult will soon be forgotten. Epictetus brought it into daily life: when you say goodbye to someone you love, remember they are mortal, and you will value them more."},"end":"Understanding this brings relief: the bad moment will also pass, and good things are enjoyed more when we know they are not eternal.","q":"Time is a sort of river of passing events, and strong is its current.","qa":"Marcus Aurelius, Meditations","bk":"Meditations, by Marcus Aurelius"},"s5":{"idea":"It is said that in Rome’s victory parades, a slave whispered to the general: “remember you are mortal”. The Stoics turned this into a daily practice. It is not a sad idea: remembering that time is limited helps us stop postponing, forgive sooner and value what we have today.","q":"It is not that we have a short time to live, but that we waste a lot of it.","qa":"Seneca, On the Shortness of Life","bk":"On the Shortness of Life, by Seneca"},"s6":{"idea":"“Amor fati” means loving fate: not just accepting what happens, but embracing it as material to grow. Epictetus advised wanting things to happen as they happen. Centuries later, Friedrich Nietzsche called it his formula for greatness. The practice is to ask yourself in every difficulty: what can I learn or build with this?","q":"Do not seek for things to happen as you wish, but wish them to happen as they do.","qa":"Epictetus, Enchiridion","bk":"The Obstacle Is the Way, by Ryan Holiday"},"s7":{"idea":"Wu wei is often translated as “non-doing”, but it does not mean laziness. It is acting without forcing, like water that flows around the stone instead of crashing into it and, over time, wears it down. In daily life it means choosing the right moment, not pushing what is not ready yet and no longer spending energy fighting the current.","q":"Nothing in the world is softer than water, yet nothing is better at overcoming the hard.","qa":"Lao Tzu, Tao Te Ching","bk":"Tao Te Ching, by Lao Tzu"},"s8":{"idea":"Upādāna, attachment, is clinging to something with the idea that without it we cannot be well: a person, an object, a position or an opinion. Buddhist non-attachment is not ceasing to love or to have, but having without depending. You can enjoy what you have knowing your peace is not in it.","q":"He who knows he has enough is rich.","qa":"Lao Tzu, Tao Te Ching","bk":"When Things Fall Apart, by Pema Chödrön"},"s9":{"idea":"","by":{"contemplativas":"Forgiveness appears in almost every spiritual tradition. In Buddhism it is cultivated through metta, loving-kindness meditation, which wishes well even to those who hurt us; in Christianity it is central, as the Lord’s Prayer reminds us. Both see it as a way to free one’s own heart, more than to absolve the other.","psicologia":"Psychology studies it as a health tool: holding a grudge keeps the body in a state of alert and stress, and forgiving is linked to less anxiety and depression. Researchers like Fred Luskin, of Stanford University, make it clear: forgiving does not mean justifying what happened or trusting again the person who hurt you, but deciding that the memory will no longer run your life."},"q":"Holding on to anger is like grasping a hot coal with the intent of throwing it at someone else; you are the one who gets burned.","qa":"A saying popularly attributed to the Buddha","bk":"The Book of Forgiving, by Desmond Tutu and Mpho Tutu"},"s10":{"idea":"Between what happens to us and what we do there is a small space. Two disciplines explain how to use it.","by":{"emocional":"Daniel Goleman explains that, faced with a threat, the amygdala (the brain’s alarm center) can “hijack” our behavior before we think. Reacting is acting from that hijack; responding is allowing a few seconds for the rational part to step in. Goleman calls this skill self-regulation, one of the pillars of emotional intelligence.","estoicismo":"Two thousand years earlier, Epictetus taught that we are not disturbed by events, but by what we think about them. The Stoics practiced not giving immediate “assent” to the first impression: pausing to ask whether it is true and whether it is up to us. Seneca, in his book On Anger, said the best remedy for anger is delay."},"q":"Men are disturbed not by things, but by the opinions they have of them.","qa":"Epictetus, Enchiridion","bk":"Emotional Intelligence, by Daniel Goleman"},"s11":{"idea":"The principle of correspondence says there is a relationship between the different planes of reality: what is above with what is below, the inner with the outer. Brought into daily life, it suggests that our outer world (relationships, order, finances) usually reflects our inner world (beliefs, emotions, habits). Changing inside is the first step to changing outside.","q":"As above, so below; as within, so without.","qa":"The Emerald Tablet (a traditional Hermetic saying)","bk":"The Kybalion, by Three Initiates"},"s12":{"idea":"The principle of rhythm teaches that everything flows in and out, like the tides, the seasons or day and night. Moods, energy and even economic times also have cycles. Knowing this helps us not believe a bad day is forever, nor that a good moment will last without care: in the fall, the rise is prepared.","q":"Everything flows, out and in; everything has its tides; all things rise and fall.","qa":"The Kybalion","bk":"The Kybalion, by Three Initiates"},"s13":{"idea":"It is the fourth noble truth in practice: eight areas of life cultivated at the same time. Right understanding, right intention, right speech, right action, right livelihood, right effort, right mindfulness and right concentration. “Right” here does not mean perfect, but balanced: a middle way between extremes.","q":"You yourself must strive; the Buddhas only point the way.","qa":"Dhammapada","bk":"The Dhammapada (teachings of the Buddha)"},"s14":{"idea":"Śūnyatā, emptiness, does not mean that nothing matters. It means that nothing exists in isolation: a cup of tea contains the rain that watered the plant, the work of whoever harvested it and the sun that made it grow. Thich Nhat Hanh called this “interbeing”. Understanding it reduces loneliness and increases gratitude and compassion.","q":"If you are a poet, you will see clearly that there is a cloud floating in this sheet of paper.","qa":"Thich Nhat Hanh","bk":"The Heart of Understanding, by Thich Nhat Hanh"},"s15":{"idea":"","by":{"metafisica":"Florence Scovel Shinn and Conny Méndez taught that words have power: what you often affirm about yourself ends up steering your life. That is why they proposed replacing negative sentences with simple affirmations, said with conviction.","psicologia":"Psychology explains it another way: your inner dialogue influences your mood and your behavior. Studies on “self-talk” show that speaking to yourself in constructive sentences improves concentration and reduces anxiety."},"q":"As a man thinketh in his heart, so is he.","qa":"Proverbs 23:7, the verse that inspired Metaphysics","bk":"The Game of Life and How to Play It, by Florence Scovel Shinn"},"m1":{"idea":"Beliefs about money form before age ten, by listening to what our parents say and do: “money is dirty”, “rich people are bad”, “there’s never enough”. Researchers call them “money scripts” and show that they influence how much we earn, spend and save as adults. Identifying them is the first step to choosing others.","q":"Getting money is one thing. Keeping it is another.","qa":"Morgan Housel (central idea of his book)","bk":"The Psychology of Money, by Morgan Housel"},"m2":{"idea":"We all have an inner dialogue that comments on what we do. Aaron Beck discovered that this dialogue often falls into “distortions”: exaggerating the bad, generalizing (“it always happens to me”) or guessing what others think. Cognitive restructuring teaches you to spot those thoughts and question them with simple questions: is it true? what evidence do I have?","q":"Men are disturbed not by things, but by the view which they take of them.","qa":"Epictetus, quoted by Albert Ellis as the origin of his therapy","bk":"Feeling Good, by David D. Burns"},"m3":{"idea":"In The Richest Man in Babylon (1926), George S. Clason tells the story of Arkad, who became rich with a simple rule: keep at least a tenth of everything he earned before paying anything else. The logic is that if you save what is left over, nothing is ever left over; if you save first, you learn to live on the rest.","q":"A part of all you earn is yours to keep.","qa":"George S. Clason, The Richest Man in Babylon","bk":"The Richest Man in Babylon, by George S. Clason"},"m4":{"idea":"A budget is not a prison, it is a map. Tracking your expenses for a month usually reveals “leaks”: small purchases that add up to a lot. A popular method is the 50/30/20 rule: half of your income for needs, 30% for wants and 20% for savings and debt. What matters is not the exact formula, but deciding where your money goes before it goes on its own.","q":"Beware of little expenses; a small leak will sink a great ship.","qa":"Benjamin Franklin","bk":"The Total Money Makeover, by Dave Ramsey"},"m5":{"idea":"An emergency fund is money set aside only for the unexpected: an illness, a repair, losing your job. The general recommendation is to gather three to six months of basic expenses, starting with a small goal. Its value is not only financial: knowing you have a backup reduces anxiety and lets you decide calmly.","q":"The prudent see danger and take refuge.","qa":"Book of Proverbs","bk":"The Psychology of Money, by Morgan Housel"},"m6":{"idea":"The “snowball” method consists of ordering your debts from smallest to largest, paying the minimum on all of them and putting every extra dollar toward the smallest. When you pay it off, that payment is added to the next one, and so the ball grows. Mathematically it is not always the cheapest, but it works because each small win gives you motivation to keep going.","q":"The borrower is slave to the lender.","qa":"Book of Proverbs","bk":"The Total Money Makeover, by Dave Ramsey"},"m7":{"idea":"Robert Kiyosaki simplified accounting into one rule: an asset puts money in your pocket (a business, an investment, a rental) and a liability takes it out (consumer debt, expenses that depreciate). The middle class often buys liabilities thinking they are assets. The proposal is to put part of your income toward acquiring things that generate income.","q":"The rich acquire assets. The poor and middle class acquire liabilities that they think are assets.","qa":"Robert Kiyosaki, Rich Dad Poor Dad","bk":"Rich Dad Poor Dad, by Robert Kiyosaki"},"m8":{"idea":"Compound interest is earning interest on interest. If you invest 100 dollars at 8% a year, in 10 years you will have about 216; in 30 years, more than 1,000, without adding anything. The secret is not how much you invest at the start, but how long you let it grow. That is why starting early, even with a little, is worth more than starting late with a lot.","q":"My wealth has come from a combination of living in America, some lucky genes, and compound interest.","qa":"Warren Buffett","bk":"The Intelligent Investor, by Benjamin Graham"},"m9":{"idea":"In his essay Compensation (1841), Emerson argues that everything in life tends toward balance: what you give, in some way, comes back. Applied to work, it means your income grows in proportion to the value you provide to others. Instead of asking “how do I earn more?”, the question is “how can I serve better, or serve more people?”.","q":"Every act rewards itself.","qa":"Ralph Waldo Emerson, Compensation","bk":"Essays, by Ralph Waldo Emerson"},"m10":{"idea":"BJ Fogg discovered that lasting habits start ridiculously small: one push-up, one written line, one dollar saved. James Clear adds that improving 1% each day makes you, after a year, about 37 times better. The trick is to focus on the system (what you do every day) more than on the goal.","q":"We are what we repeatedly do. Excellence, then, is not an act, but a habit.","qa":"Will Durant, summarizing Aristotle","bk":"Atomic Habits, by James Clear"},"m11":{"idea":"Carol Dweck found two ways of seeing our abilities. With a fixed mindset, a failure confirms that “I’m no good at this”. With a growth mindset, failure is information: it shows what is left to learn. Her studies with thousands of students show that this second way of thinking can be learned and improves results.","q":"I have not failed. I’ve just found 10,000 ways that won’t work.","qa":"Attributed to Thomas Edison","bk":"Mindset: The New Psychology of Success, by Carol Dweck"},"m12":{"idea":"Diversifying is spreading money across different investments so that if one does badly, the others make up for it. Harry Markowitz showed in 1952 that a varied portfolio reduces risk without giving up much return. The same goes for income: depending on a single source makes you vulnerable.","q":"Invest in seven ventures, yes, in eight; you do not know what disaster may come.","qa":"Ecclesiastes","bk":"A Random Walk Down Wall Street, by Burton Malkiel"},"m13":{"idea":"Gary Becker showed that education and skills are an investment with a return: whoever learns something valuable increases what they can earn throughout their life. Your talent is the only asset no one can take away from you, and it multiplies as you use it. Investing time and money in learning is usually the most profitable investment.","q":"An investment in knowledge pays the best interest.","qa":"Benjamin Franklin","bk":"So Good They Can’t Ignore You, by Cal Newport"},"m14":{"idea":"","by":{"metafisica":"Wallace D. Wattles wrote in 1910 that gratitude keeps the mind focused on what works and opens the door to creating more value. For Metaphysics, prosperity begins by recognizing the abundance that already exists in your life.","dinero":"The psychology of money agrees on something practical: when you decide from fear, you spend impulsively or freeze. Gratitude reduces that anxiety and helps you make better financial decisions."},"q":"Be grateful for what you have, and you will receive more.","qa":"An idea of Wallace D. Wattles","bk":"The Science of Getting Rich, by Wallace D. Wattles"},"v1":{"idea":"Our internal clock resets every morning with light. Getting natural light in the first hour of the day tells the body it is daytime: cortisol rises in a healthy way, mood improves and, about 14 to 16 hours later, melatonin is released to help us sleep. Drinking water when you wake up replaces what was lost during the night.","q":"Early to bed and early to rise makes a man healthy, wealthy and wise.","qa":"Benjamin Franklin","bk":"Why We Sleep, by Matthew Walker"},"v2":{"idea":"The World Health Organization recommends at least 150 minutes of moderate activity per week, about 22 minutes a day. Brisk walking meets that goal and is linked to a lower risk of heart disease, diabetes and depression. Walking also helps you think: many philosophers, from Aristotle to Nietzsche, thought while walking.","q":"Walking is man’s best medicine.","qa":"Attributed to Hippocrates","bk":"Exercised, by Daniel Lieberman"},"v3":{"idea":"The NOVA classification, created at the University of São Paulo, divides foods by how processed they are: from natural (fruit, grains, eggs) to ultra-processed (industrial products with ingredients you would not use in your kitchen). Many studies link high consumption of ultra-processed foods with a higher risk of obesity and chronic disease.","q":"Eat food. Not too much. Mostly plants.","qa":"Michael Pollan","bk":"Food Rules, by Michael Pollan"},"v4":{"idea":"Sleep hygiene is the set of habits that prepare the body to rest: regular schedules, natural light during the day, little light at night, avoiding caffeine in the afternoon and a cool, dark bedroom. Good sleep does not start when you turn off the light: it starts when you wake up, because what you do during the day defines how you sleep at night.","q":"Sleep is that golden chain that ties health and our bodies together.","qa":"Thomas Dekker","bk":"Why We Sleep, by Matthew Walker"},"v5":{"idea":"","by":{"contemplativas":"The yoga of India calls these techniques pranayama, “control of the vital energy”, and has practiced them for thousands of years; in Buddhism, anapanasati meditation is simply observing the breath. For these traditions, breathing is the bridge between body and mind.","estilo":"Physiology explains why they work: breathing slowly, especially with exhalations longer than inhalations, activates the parasympathetic nervous system, which is in charge of calm. In a few minutes heart rate and blood pressure drop. That is why lifestyle medicine recommends it as a tool against stress."},"q":"Feelings come and go like clouds in a windy sky. Conscious breathing is my anchor.","qa":"Thich Nhat Hanh","bk":"Breath, by James Nestor"},"v6":{"idea":"Harvard’s “Healthy Eating Plate” offers a simple visual guide: half the plate with vegetables and fruit, a quarter with whole grains and a quarter with healthy protein, along with water. Plants provide fiber, vitamins and antioxidants, and feed the good bacteria in the gut.","q":"Let food be thy medicine.","qa":"A saying attributed to Hippocrates","bk":"Eat, Drink, and Be Healthy, by Walter Willett"},"v7":{"idea":"From age 30 we slowly lose muscle mass, and that loss speeds up with age. Strength training, at least two days a week according to the WHO, protects bones, improves balance, regulates blood sugar and preserves independence in old age. You do not need a gym: body weight is enough to start.","q":"Lack of activity destroys the good condition of every human being, while movement and methodical physical exercise save it and preserve it.","qa":"Attributed to Plato","bk":"Outlive, by Peter Attia"},"v8":{"idea":"","by":{"atencion":"Mindful eating comes from the Buddhist practice of being present in every action. Thich Nhat Hanh taught people to eat in silence, chewing slowly and noticing the flavors, the textures and the journey each food made to reach the table.","nutricion":"Nutrition explains its benefits: the stomach takes about 20 minutes to tell the brain it is full, so eating slowly helps you eat just enough. Chewing well improves digestion, and eating without screens reduces binges."},"q":"When eating, just eat.","qa":"Zen proverb","bk":"Savor, by Thich Nhat Hanh and Lilian Cheung"},"v9":{"idea":"The light from screens, especially blue light, tells the brain it is still daytime and delays the release of melatonin, the sleep hormone. The content also stimulates the mind. Putting screens away 30 to 60 minutes before bed, and swapping them for reading or conversation, usually improves the quality of rest.","q":"A good laugh and a long sleep are the best cures.","qa":"Irish proverb","bk":"Why We Sleep, by Matthew Walker"},"v10":{"idea":"“Free sugars” are those added to products plus those in juices and honey. The WHO recommends they be less than 10% of daily energy, ideally down to 5%: about six teaspoons a day. Many “savory” or “healthy” products, like sauces, bread or yogurt, contain hidden sugar; reading labels is the best defense.","q":"Enough is as good as a feast.","qa":"Popular saying","bk":"Sugar Blues, by William Dufty"},"v11":{"idea":"Spending many hours sitting affects health even in people who exercise. Research shows that getting up for a few minutes every 30 to 60 minutes improves circulation, blood sugar and concentration. “Active breaks” are small interruptions that add up over the day.","q":"Only thoughts reached by walking have value.","qa":"Friedrich Nietzsche, Twilight of the Idols","bk":"Exercised, by Daniel Lieberman"},"v12":{"idea":"In 1982, the government of Japan promoted shinrin-yoku, “forest bathing”: walking slowly among trees with all five senses. Studies show it lowers cortisol, blood pressure and heart rate, and improves mood. You do not need a forest: a park, a garden or some time under the sky also help.","q":"Look deep into nature, and then you will understand everything better.","qa":"Attributed to Albert Einstein","bk":"Forest Bathing (Shinrin-yoku), by Qing Li"},"v13":{"idea":"","by":{"estilo":"Lifestyle medicine counts healthy relationships as one of its six pillars of health. Research shows that prolonged loneliness affects health as much as smoking and raises the risk of heart disease.","psicologia":"The Harvard Study of Adult Development has followed the lives of hundreds of people since 1938. Its clearest conclusion: what best predicts a long, happy life is not money or fame, but the quality of our relationships."},"end":"Caring for the people close to you is also caring for your body.","q":"Without friends no one would choose to live, though he had all other goods.","qa":"Aristotle, Nicomachean Ethics","bk":"The Good Life, by Robert Waldinger and Marc Schulz"},"v14":{"idea":"","by":{"metafisica":"James Allen compared the mind to a garden: if you do not sow good ideas, weeds grow on their own. For him, a person’s character and mood are the fruit of the thoughts they cultivate each day.","psicologia":"Cognitive therapy, created by Aaron Beck, reached a similar conclusion with scientific method: many emotions are born from automatic thoughts, and learning to review them reduces anxiety and stress."},"q":"As a man thinketh in his heart, so is he.","qa":"Proverbs 23:7, the epigraph of James Allen’s book","bk":"As a Man Thinketh, by James Allen"}},"pillars":{"s":{"name":"Spirit","day":"Monday"},"m":{"name":"Prosperity","day":"Wednesday"},"v":{"name":"Vitality","day":"Friday"}},"levels":[{"name":"Origin","d":"You begin your path."},{"name":"Awakening","d":"4 complete weeks."},{"name":"Practice","d":"8 weeks and your first habits."},{"name":"Consistency","d":"13 weeks. 3-month path."},{"name":"Clarity","d":"26 weeks. 6-month path."},{"name":"Mastery","d":"39 weeks of practice."},{"name":"Fulfillment","d":"52 weeks. The full spiral."}],"days":[{"s":"Mon","c":"M","n":"Monday"},{"s":"Tue","c":"T","n":"Tuesday"},{"s":"Wed","c":"W","n":"Wednesday"},{"s":"Thu","c":"T","n":"Thursday"},{"s":"Fri","c":"F","n":"Friday"},{"s":"Sat","c":"S","n":"Saturday"},{"s":"Sun","c":"S","n":"Sunday"}],"areas":[{"n":"Inner peace","q":"How much calm do you feel in your daily life?","h":"Think about how much you worry and how easy or hard it is for you to be at peace with yourself.","lo":"None","hi":"A lot"},{"n":"Purpose","q":"How clear is the direction of your life?","h":"Think about whether you have goals that motivate you and whether what you do each day feels meaningful to you.","lo":"Not clear","hi":"Very clear"},{"n":"Relationships","q":"How do you feel about your relationships?","h":"Partner, family and friends: the support you give and receive, and how you handle conflict.","lo":"Very bad","hi":"Very good"},{"n":"Finances","q":"How much peace of mind does your financial situation give you?","h":"Think about your debts, your savings and whether you have a cushion for the unexpected.","lo":"None","hi":"A lot"},{"n":"Work","q":"How satisfied do you feel with your work?","h":"Think about your income, your chances to grow and whether you make good use of your talents.","lo":"Not at all","hi":"Completely"},{"n":"Physical health","q":"How would you rate the care you give your body?","h":"Think about how you eat, how much you move and how you feel about your weight.","lo":"Very low","hi":"Excellent"},{"n":"Rest","q":"How well do you rest and how much energy do you have?","h":"Think about how you sleep and how you feel at the end of the day.","lo":"Very little","hi":"A lot"},{"n":"Emotions","q":"How well do you handle stress and your emotions?","h":"Think about how you react when things get complicated or don’t turn out as you expected.","lo":"Very badly","hi":"Very well"}],"books":{"paz":[{"t":"The Sermon on the Mount","a":"Emmet Fox","y":"1934","why":"A classic of Metaphysics that reads the teachings of Jesus as a practical guide to living calmly and without resentment."},{"t":"The Power of Now","a":"Eckhart Tolle","y":"1997","why":"It teaches you to step out of mental noise and return to the present, which is where calm appears."},{"t":"Meditations","a":"Marcus Aurelius","y":"2nd century","why":"The personal notes of an emperor who sought serenity in the midst of wars and great responsibilities."}],"proposito":[{"t":"Man’s Search for Meaning","a":"Viktor Frankl","y":"1946","why":"A psychiatrist who survived the concentration camps shows that whoever has a “why” can bear almost any “how”."},{"t":"Ikigai","a":"Héctor García and Francesc Miralles","y":"2016","why":"It explores the Japanese idea of having a reason to get up every morning."},{"t":"As a Man Thinketh","a":"James Allen","y":"1903","why":"A short classic of Metaphysics on how the thoughts you cultivate shape your direction and your character."}],"relaciones":[{"t":"The Four Agreements","a":"Don Miguel Ruiz","y":"1997","why":"Four simple commitments to relate better and stop taking everything personally."},{"t":"Nonviolent Communication","a":"Marshall Rosenberg","y":"1999","why":"A practical method to say what you feel and need without attacking or getting defensive."},{"t":"The Game of Life and How to Play It","a":"Florence Scovel Shinn","y":"1925","why":"A classic of Metaphysics on how your words and your attitude change the way you relate to others."}],"finanzas":[{"t":"The Psychology of Money","a":"Morgan Housel","y":"2020","why":"It shows that handling money well depends more on your behavior than on how much you know."},{"t":"The Richest Man in Babylon","a":"George S. Clason","y":"1926","why":"Simple stories about saving, getting out of debt and growing what you have."},{"t":"The Science of Getting Rich","a":"Wallace D. Wattles","y":"1910","why":"A classic of Metaphysics that links prosperity with gratitude and with creating value for others, instead of competing."}],"trabajo":[{"t":"Atomic Habits","a":"James Clear","y":"2018","why":"How small daily changes add up until they transform your results."},{"t":"Mindset: The New Psychology of Success","a":"Carol Dweck","y":"2006","why":"It explains why believing you can learn changes what you achieve."},{"t":"The Power of Your Subconscious Mind","a":"Joseph Murphy","y":"1963","why":"It shows how what you tell yourself every day about yourself and your work ends up guiding your decisions."}],"salud":[{"t":"The Blue Zones","a":"Dan Buettner","y":"2008","why":"How the communities where the most people reach one hundred in good health eat, move and live together."},{"t":"Atomic Habits","a":"James Clear","y":"2018","why":"To turn caring for your body into a routine that keeps itself going."}],"descanso":[{"t":"Why We Sleep","a":"Matthew Walker","y":"2017","why":"A neuroscientist explains what sleep does for your body and mind, and how to sleep better."}],"emociones":[{"t":"Emotional Intelligence","a":"Daniel Goleman","y":"1995","why":"How to recognize and manage your emotions, and why that matters as much as talent."},{"t":"The Power of Now","a":"Eckhart Tolle","y":"1997","why":"It helps you observe what you feel without letting it drag you along."},{"t":"As a Man Thinketh","a":"James Allen","y":"1903","why":"A short book on how the thoughts you cultivate become your mood and your character."}]},"authors":[{"n":"Marcus Aurelius","k":"Roman emperor and Stoic philosopher · 121–180","t":"He ruled Rome for almost twenty years of wars and epidemics. Every night he wrote notes to himself on how to be a better person. He never meant to publish them: today we know them as the “Meditations”.","i":"You don’t control what happens, but you do control how you respond."},{"n":"Seneca","k":"Roman Stoic philosopher · c. 4 BC–AD 65","t":"He was a writer, politician and adviser to the emperor Nero. In his letters to his friend Lucilius he left practical advice on time, wealth and serenity.","i":"Time is the only thing that truly belongs to us: take care of it."},{"n":"Epictetus","k":"Greek Stoic philosopher · c. 50–135","t":"He was born a slave and became one of the most influential teachers of his time. He taught that freedom begins in the mind.","i":"Separate what is up to you from what is not, and put your energy only into the first."},{"n":"Lao Tzu","k":"Chinese sage of Taoism · according to tradition, 6th century BC","t":"He is credited with the Tao Te Ching, a short book of 81 poems about living in harmony with the natural rhythm of things.","i":"Water is soft, and yet it overcomes stone through persistence."},{"n":"Siddhartha Gautama, the Buddha","k":"Founder of Buddhism · c. 5th century BC","t":"He left a prince’s life to understand why we suffer. His answer: much of our suffering is born from clinging to what changes.","i":"Attention to the present moment calms the mind."},{"n":"Viktor Frankl","k":"Austrian psychiatrist · 1905–1997","t":"He survived the concentration camps and created logotherapy, a form of therapy focused on finding meaning in life.","i":"Between what happens to you and your response there is a space: that is where your freedom lies."},{"n":"James Allen","k":"British writer of Metaphysics · 1864–1912","t":"In 1903 he published “As a Man Thinketh”, a short book that inspired generations of personal development authors.","i":"Your thoughts are seeds: what you sow in your mind ends up appearing in your life."},{"n":"Conny Méndez","k":"Venezuelan writer and composer · 1898–1979","t":"She was a cartoonist, singer and composer before devoting herself to Metaphysics. Her books brought it to millions of readers in Latin America.","i":"What you affirm with your words becomes your way of seeing the world."},{"n":"Joseph Murphy","k":"Irish author of Metaphysics · 1898–1981","t":"A minister and lecturer who lived in the United States. His book “The Power of Your Subconscious Mind” (1963) is one of the most widely read on the subject.","i":"What you repeat in your mind every day ends up guiding your habits."},{"n":"Florence Scovel Shinn","k":"American illustrator and writer · 1871–1940","t":"A New York artist who in 1925 published “The Game of Life and How to Play It”, about the power of words and faith in everyday life.","i":"Watch your words: with them you describe, and also build, your day."},{"n":"Carol Dweck","k":"Psychologist at Stanford University · 1946","t":"After decades of research she described the “growth mindset”: believing your abilities develop with effort and practice.","i":"You haven’t managed it yet: the key word is “yet”."}],"beliefs":[{"f":"I’m not good with money","r":"I am learning to manage my money, step by step.","e":"Think of a time you paid something on time or saved even a little. That is already managing money: it is about practicing it more often."},{"f":"It’s too late to change","r":"Today is a good day to start something small.","e":"The brain keeps forming new connections throughout life. Many people start studying, exercising or building a business after 50 and 60."},{"f":"I have no time for myself","r":"I can give myself ten minutes a day.","e":"Look at how much time you spend on your phone without a purpose. Ten minutes a day is more than an hour a week devoted to you."},{"f":"If I fail, it’s because I’m no good","r":"Failing is part of learning.","e":"Carol Dweck’s research shows that those who see mistakes as information, and not as a judgment of their worth, make more progress."},{"f":"This is just how I am and I can’t change","r":"I can choose how to respond today.","e":"The way you are is also made of habits, and habits can be changed with small repetitions."},{"f":"I don’t deserve to do well","r":"I deserve to grow, just like anyone else.","e":"This idea usually comes from past experiences, not from today’s facts. Ask yourself who you first heard it from."}],"moods":[{"l":"Very bad"},{"l":"Bad"},{"l":"So-so"},{"l":"Good"},{"l":"Very good"}],"diaQ":{"s":["What gave you peace today, even if it was something small?","Who did you feel connected to today, and why?","What would you say to yourself from a year ago?","What are you carrying that you could let go of?"],"m":["What decision did you make today with your future self in mind?","What did you learn today that makes you more valuable at work?","How did you feel about money today? Why?","Which expense this week brought you closer to your goal, and which took you further away?"],"v":["How did you treat your body today?","What gave you energy today and what took it away?","What small health habit do you want to keep up tomorrow?","How did you sleep last night and what could you do differently today?"],"g":["What made you smile today?","What step, however small, did you take today toward your goal?","What situation today could you have handled better, and how?","What are you proud of this week?"]},"diaStories":[{"n":"Marcus Aurelius","y":"2nd century","t":"The most powerful emperor of his time wrote to himself every night: how to keep calm, be fair and accept what he could not change. Those notes, the “Meditations”, were never meant to be published and today they are one of the most widely read books of practical wisdom in the world."},{"n":"Leonardo da Vinci","y":"1452–1519","t":"He filled thousands of pages with drawings, questions and ideas: from flying machines to the human body. His notebooks show that writing was his way of thinking."},{"n":"Benjamin Franklin","y":"1706–1790","t":"As a young man he chose thirteen virtues, such as order and temperance, and every day he recorded in a table how he had done with them. He said that record made him a better person."},{"n":"Charles Darwin","y":"1809–1882","t":"During his voyage around the world he wrote down everything he observed. Those notebooks were the seed of the theory of evolution, which changed science."},{"n":"Anne Frank","y":"1929–1945","t":"Hidden with her family during the Second World War, she wrote her diary between the ages of 13 and 15. Today it is one of the most widely read books in history and a testimony of hope."},{"n":"Frida Kahlo","y":"1907–1954","t":"In her last ten years she kept a diary of writings and colorful drawings in which she expressed her pain, her love and her creative strength."}],"countries":["Argentina","Australia","Bolivia","Canada","Chile","Colombia","Costa Rica","Cuba","Dominican Republic","Ecuador","El Salvador","Guatemala","Honduras","India","Ireland","Mexico","New Zealand","Nicaragua","Panama","Paraguay","Peru","Philippines","Puerto Rico","South Africa","Spain","United Kingdom","United States","Uruguay","Venezuela"]};
